// How many pipelines a scene change may leave resident before it releases the
// least recently drawn ones (0: release everything the new scene doesn't use).
// Browsers keep the strict policy for Safari's limit. Phones keep a budget:
// releasing the board's ~900 pipelines for every minigame meant rebuilding
// them all on the way back (1.7 s of both compile threads on the S22+, and
// 100-260 ms scene-start stalls), and a few minigames' worth fits easily.
// MP6_PIPELINE_RESIDENT_BUDGET=<n> overrides it.
#ifdef __EMSCRIPTEN__
constexpr size_t SceneReleaseBudget = 0;
#else
constexpr size_t SceneReleaseBudget = 2000;
#endif

static size_t scene_release_budget() {
  static const size_t budget = [] {
    const char* env = std::getenv("MP6_PIPELINE_RESIDENT_BUDGET");
    return env != nullptr && env[0] != '\0' ? static_cast<size_t>(std::strtoul(env, nullptr, 10))
                                            : SceneReleaseBudget;
  }();
  return budget;
}
