struct CachedPipeline {
  wgpu::RenderPipeline pipeline;
  uint32_t firstFrameUsed = UINT32_MAX;
  uint32_t lastFrameUsed = 0; // scene changes may release pipelines not used lately
  std::optional<gx::ShaderInfo> shaderInfo;
  uint32_t shaderInfoAlignment = 0;
};

struct PendingPipeline {
  PipelineRef hash;
  uint32_t firstFrameUsed = UINT32_MAX;
  NewPipelineCallback create;
  bool prewarm = false; // queued ahead of use (scene set), not by a draw
  bool warmup = false;    // part of the first-launch build (counted in its progress)
  bool transient = false; // first-launch build only: released once built
};

struct PipelineCacheWrite {
  ShaderType type;
  PipelineRef hash;
  uint32_t configVersion;
  ByteBuffer config;
  uint32_t firstFrameUsed = UINT32_MAX;
  // Set: this write records (type, hash) in that scene's set instead.
  uint32_t scene = NoScene;
  uint32_t firstUse = 0;
  bool mainTarget = false;
};

